    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 2, index: 16 }] }))).toBeNull();
    expect(replayGame(JSON.stringify({ ...base, actions: Array(10001).fill({ atMs: 0, index: 0 }) }))).toBeNull();
  });
});

